// OP-159 m.47 (c), (f), TN-141, EI-18: the browser's own device key for a founding or an administrator
// invitation. Its P-256 key is generated by WebCrypto as non-extractable and kept in IndexedDB on
// this origin, as the account pages keep theirs; only its public `COSE_Key` leaves the browser. A
// founder's key is the tenant's founding root (`P = root_party(K)`).
import { loadKernel } from "@esuiss/access";

const DB = "access-account";
const STORE = "instances";

function b64url(bytes: Uint8Array): string {
  let s = "";
  for (const b of bytes) s += String.fromCharCode(b);
  return btoa(s).replaceAll("+", "-").replaceAll("/", "_").replace(/=+$/, "");
}

/** Keeps `record` in the account pages' key store. */
function keep(record: { readonly id: string; readonly key: CryptoKey; readonly kid: Uint8Array }) {
  return new Promise<void>((resolve, reject) => {
    const r = indexedDB.open(DB, 1);
    r.onupgradeneeded = () => {
      r.result.createObjectStore(STORE, { keyPath: "id" });
    };
    r.onerror = () => {
      reject(r.error ?? new Error("indexeddb"));
    };
    r.onsuccess = () => {
      const put = r.result.transaction(STORE, "readwrite").objectStore(STORE).put(record);
      put.onsuccess = () => {
        resolve();
      };
      put.onerror = () => {
        reject(put.error ?? new Error("indexeddb"));
      };
    };
  });
}

/** A device key made for `purpose`: its public `COSE_Key`, unpadded base64url. */
export interface DeviceKey {
  readonly cose: string;
}

/**
 * A new non-extractable P-256 key, kept in IndexedDB under `slug` and `purpose`, and its public
 * `COSE_Key` as the Kernel encodes it.
 */
export async function makeKey(slug: string, purpose: "founder" | "admin"): Promise<DeviceKey> {
  const k = await loadKernel();
  const pair = await crypto.subtle.generateKey({ name: "ECDSA", namedCurve: "P-256" }, false, [
    "sign",
  ]);
  const raw = new Uint8Array(await crypto.subtle.exportKey("raw", pair.publicKey));
  const [x, y] = [raw.slice(1, 33), raw.slice(33, 65)];
  const kid = k.thumbprintP256(x, y);
  const cose = b64url(k.coseKeyP256(x, y));
  await keep({ id: `${slug}/${purpose}/${b64url(kid)}`, key: pair.privateKey, kid });
  return { cose };
}
